from __future__ import annotations

from types import MethodType
from typing import Any

from torch.distributions import Bernoulli

from fasttransform import DisplayedTransform, retain_type
from fasttransform.transform import _is_tuple, ifnone
from plum import NotFoundLookupError

from .imports import *

# %% auto 0
__all__ = ['BatchRandTransform']

# %% ../nbs/transform.ipynb 5
class BatchRandTransform(DisplayedTransform):
    "Randomly selects a subset of batch `b` to apply transform with per item probability `p` in `before_call`"
    do,supports,split_idx = True,[],0
    def __init__(self,
        p:Numeric=1., # Probability of applying Transform to each batch item
        before_call:Callable[[Tensor|tuple[Tensor,...],int],None]|None=None, # Batch preprocessing function
        **kwargs
    ):
        store_attr('p')
        super().__init__(**kwargs)
        self.before_call = ifnone(before_call,self.before_call)
        self.bernoulli = Bernoulli(p)

    def before_call(self,
        b:Tensor|tuple[Tensor,...], # Batch item(s)
        split_idx:int # Train (0) or valid (1) index
    ):
        "Randomly select `self.idxs` and set `self.do` based on `self.p` if not valid `split_idx`"
        self.idxs = self.bernoulli.sample((find_bs(b),)).bool() if not split_idx and self.p<1. else torch.ones(find_bs(b)).bool()
        self.do = self.p==1. or self.idxs.sum() > 0

    def __call__(self, *args, split_idx=None, **kwargs):
        return self._call('encodes', *args, split_idx=split_idx, **kwargs)

    def decode(self, *args, split_idx=None, **kwargs):
        return self._call('decodes', *args, split_idx=split_idx, **kwargs)

    def setup(self, items=None, train_setup=False):
        train_setup = train_setup if self.train_setup is None else self.train_setup
        items = getattr(items, 'train', items) if train_setup else items
        try: return self.setups(items)
        except (AttributeError, NotFoundLookupError): return None

    def _call(self, nm, *args, split_idx=None, **kwargs):
        "Call method `nm` with batch preprocessing and random selection"
        self.before_call(args[0], split_idx=split_idx)
        if not self.do: return args[0]
        if split_idx!=self.split_idx and self.split_idx is not None: return args[0]
        if not hasattr(self, nm): return args[0]
        return self._do_call(nm, *args, **kwargs)

    def _do_call(self, nm, *args, **kwargs):
        "Override `Transform._do_call` to apply transform to `x[self.idxs]`"
        if _is_tuple(x:=args[0]):
            res = tuple(self._do_call(nm, x_, *args[1:], **kwargs) for x_ in x)
            return retain_type(res, x, Any)
        f = getattr(self, nm)

        # For regular instance methods, we need different handling
        if isinstance(f, MethodType):
            # This is a bound method - call it directly on selected indices
            return retain_type(self._do_f_instance_method(f, x, args[1:], **kwargs), x, Any)
        else:
            # Check if this is a plumb method with method resolution
            if hasattr(f, '_resolve_method_with_cache'):
                try:
                    f_args = (self,) + args
                    method, ret_type = f._resolve_method_with_cache(f_args)
                    return retain_type(self._do_f_with_method(method, x, f_args[1:], **kwargs), x, ret_type)
                except NotFoundLookupError:
                    return x
            else:
                # Regular function - apply directly with index selection
                f_args = args
                return retain_type(self._do_f_regular(f, x, f_args[1:], **kwargs), x, Any)

    def _do_f_with_method(self, method, x, f_args, **kwargs):
        "Apply plumb method to `x[self.idxs]` only"
        result = method(x[self.idxs], *f_args, **kwargs)
        if result is not None:
            x[self.idxs] = result
        return x

    def _do_f_instance_method(self, f, x, f_args, **kwargs):
        "Apply bound instance method to `x[self.idxs]` only"
        result = f(x[self.idxs], *f_args, **kwargs)
        if result is not None:
            x[self.idxs] = result
        return x

    def _do_f_regular(self, f, x, f_args, **kwargs):
        "Apply regular method to `x[self.idxs]` only"
        result = f(x[self.idxs], *f_args, **kwargs)
        if result is not None:
            x[self.idxs] = result
        return x
